prismaticChemtrails.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 fullResolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform float dispersion;    // 0.0-1.0, radial spectral dispersion strength
uniform float driftAmount;   // 0.0-0.5, wisp drift oscillation amplitude
uniform float hueOffset;     // 0.0-1.0, iridescent sheen hue shift
uniform float mixWisp;       // 0.0-1.0, wisp modulation of dispersion
uniform float prismIntensity; // 0.0-2.0, prism effect strength
uniform float trailDensity;  // 0.5-8.0, chemtrail wisp density

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float valueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        v += amp * valueNoise(p);
        p = p * 2.02 + vec2(1.7, 9.2);
        amp *= 0.5;
    }
    return v;
}

// Saturated rainbow palette: red at t=0, through spectrum to violet
vec3 rainbowPalette(float t) {
    vec3 c = 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
    // boost saturation
    float g = dot(c, vec3(0.299, 0.587, 0.114));
    return mix(vec3(g), c, 1.6);
}

// Pale steel-blue/white base tint for chemtrail wisps
vec3 wispTint(float density) {
    vec3 base = vec3(0.85, 0.88, 0.92);
    return mix(vec3(1.0), base, clamp(density, 0.0, 1.0));
}

float gaussianWeight(float x, float sigma) {
    return exp(-(x * x) / (2.0 * sigma * sigma));
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// Radial prism bloom: sharp at the optical center, wider at the edges.
    float aspect = resolution.x / resolution.y;
    float centerDist = length(centered);
    float edgeBloom = smoothstep(0.0, 0.85, centerDist);
    vec2 radialDirection = centered / max(centerDist, 0.0001);
    radialDirection.x /= aspect;

    vec2 wispDomain = vec2(uv.x, uv.y * 6.0) * trailDensity;
    vec2 driftA = vec2(driftAmount * sin(t), 0.0);
    vec2 driftB = vec2(-driftAmount * cos(t), 0.0);
    vec2 organicMotion = timeCircle * 0.3;

    float localWispA = fbm(wispDomain + driftA + organicMotion);
    float localWispB = fbm(wispDomain * 1.23 + driftB
                         - organicMotion + vec2(8.1, 3.7));
    float localDensity = smoothstep(
        0.36, 0.69, localWispA * 0.65 + localWispB * 0.35
    );

    float breathing = 0.8 + 0.2 * sin(t);
    float dispersionWidth = dispersion * breathing * 0.16;
    dispersionWidth *= mix(1.0, 0.35 + 1.35 * localDensity, mixWisp);
    dispersionWidth *= clamp(prismIntensity, 0.0, 2.0);

    float sheenShift = hueOffset + 0.05 * sin(t * 2.0);
    vec3 spectralSum = vec3(0.0);
    vec3 spectralNormalization = vec3(0.0);
    vec3 neutralSum = vec3(0.0);
    float totalWeight = 0.0;

    // Each tap views a complete airy sky with dissolving horizontal trails.
    for (int tap = 0; tap < 18; ++tap) {
        float tapPosition = float(tap) / 17.0;
        float signedPosition = tapPosition - 0.5;
        vec2 sampleUV = uv + radialDirection
                     * signedPosition * dispersionWidth * centerDist;

        vec3 sky = mix(
            vec3(0.88, 0.94, 0.99),
            vec3(0.34, 0.63, 0.87),
            smoothstep(0.0, 1.0, sampleUV.y)
        );

        vec2 domain = vec2(sampleUV.x, sampleUV.y * 6.0)
                    * trailDensity;
        float noiseA = fbm(domain + driftA + organicMotion);
        float noiseB = fbm(domain * 1.23 + driftB
                        - organicMotion + vec2(8.1, 3.7));
        float vapor = smoothstep(0.34, 0.73, 0.65 * noiseA + 0.35 * noiseB);

        // Explicit narrow trail coverage, warped and eroded into soft wisps.
        float trails = 0.0;
        for (int trail = 0; trail < 6; ++trail) {
            float id = float(trail);
            float seed = hash(vec2(id + 1.0, 17.2));
            float layerSign = (trail == 0 || trail == 2 || trail == 4)
                            ? 1.0 : -1.0;
            float pendulum = layerSign > 0.0
                           ? driftAmount * sin(t)
                           : -driftAmount * cos(t);
            float trailX = sampleUV.x + pendulum;
            float baseHeight = 0.13 + id * 0.145;
            float bend = 0.013 * sin(trailX * 7.0 + seed * TAU);
            bend += (noiseA - 0.5) * 0.075;
            float distanceToTrail = abs(sampleUV.y - baseHeight - bend);
            float width = (0.007 + 0.010 * seed)
                        * (0.65 + 0.35 * vapor)
                        * sqrt(max(trailDensity, 0.5) / 3.0);
            float coverage = 1.0 - smoothstep(width, width * 3.6, distanceToTrail);
            float segment = smoothstep(-0.15, 0.12, trailX + seed * 0.2)
                          * (1.0 - smoothstep(0.78, 1.2, trailX - seed * 0.15));
            float dissolution = smoothstep(0.28, 0.65,
                mix(noiseA, noiseB, seed));
            trails = max(trails, coverage * segment * dissolution);
        }

        float density = clamp(trails * 0.94 + vapor * 0.23, 0.0, 1.0);
        vec3 paleWisp = wispTint(density);
        vec3 sheen = clamp(rainbowPalette(
            sampleUV.x * 0.55 + sampleUV.y * 0.22
            + sheenShift + noiseB * 0.25
        ), 0.0, 1.0);
        sheen = mix(vec3(1.0), sheen, 0.65);
        float sheenMask = smoothstep(0.25, 0.85, density) * edgeBloom;
        sheenMask *= clamp(prismIntensity * 0.65, 0.0, 0.9);
        vec3 cloudColor = mix(paleWisp, sheen, sheenMask);
        vec3 sceneColor = mix(sky, cloudColor, density * 0.88);

        // Positive saturated full-spectrum weights, red outward/violet inward.
        vec3 spectrum = clamp(
            rainbowPalette((1.0 - tapPosition) * 0.78), 0.0, 1.0
        );
        spectrum = mix(vec3(0.08), vec3(1.0), spectrum);
        float weight = gaussianWeight(signedPosition, 0.27);
        weight *= 1.0 - smoothstep(0.38, 0.62, abs(signedPosition));

        spectralSum += sceneColor * spectrum * weight;
        spectralNormalization += spectrum * weight;
        neutralSum += sceneColor * weight;
        totalWeight += weight;
    }

    vec3 dispersedColor = spectralSum / max(spectralNormalization, vec3(0.0001));
    vec3 neutralColor = neutralSum / max(totalWeight, 0.0001);
    float prismBlend = clamp(prismIntensity, 0.0, 1.0);
    vec3 color = mix(neutralColor, dispersedColor, prismBlend);
    color = max(color, vec3(0.0));

//  Color Output 
    // Gentle center-weighted exposure so the frame core stays bright and airy
    // while the prismatic bloom dissolves outward toward the frame edges.
    float centerProtect = 1.0 - 0.18 * edgeBloom;
    color *= centerProtect;

    // Soft tonal shaping to keep pastels airy without clipping highlights.
    color = color / (color + vec3(0.85)) * 1.65;
    color = pow(clamp(color, 0.0, 1.0), vec3(0.92));

    // Final pastel lift toward a bright sky-white base.
    color = mix(color, mix(color, vec3(1.0), 0.12), smoothstep(0.4, 1.0, centerDist));

    fragColor = vec4(color, 1.0);
}
